def described_vocabulary(name: str, raw: str) -> tuple[bool, str] | None:
    """The value of the described enum `name` whose raw spelling is `raw` (an
    integer's decimal spelling for an int32 enum): whether the description lists it,
    and its raw spelling read back. None for a name the description does not define,
    or a spelling that is not an int32 enum's raw value."""
    cls = DESCRIBED_VOCABULARIES.get(name)
    if cls is None:
        return None
    if issubclass(cls, IntEnum):
        try:
            number = int(raw, 10)
        except ValueError:
            return None
        if not -(2**31) <= number < 2**31:
            return None
        value = cls(number)
        return value.known, str(int(value))
    if issubclass(cls, StrEnum):
        member = cls(raw)
        return member.known, str(member)
    return cls.known(raw), raw
